/**
 * Looks up a medicine name against the brand composition map.
 * Case-insensitive partial matching on brand name keywords.
 * Returns the matching entry or null if not found.
 * @param {string} medicineName
 * @returns {object|null}
 */
function lookupBrand(medicineName) {
  if (!medicineName || typeof medicineName !== "string") {
    return null;
  }
  var searchTerm = medicineName.toLowerCase().trim();

  // Exact key match
  if (brandCompositionMap[searchTerm]) {
    return brandCompositionMap[searchTerm];
  }

  // Check all keys for the best partial match
  var bestMatch = null;
  var bestLength = 0;
  var keys = Object.keys(brandCompositionMap);

  for (var i = 0; i < keys.length; i++) {
    var key = keys[i];
    // Exact match on key
    if (searchTerm === key) {
      return brandCompositionMap[key];
    }
    // Check if the search term contains the key or vice versa
    if (searchTerm.indexOf(key) !== -1 || key.indexOf(searchTerm) !== -1) {
      if (key.length > bestLength) {
        bestMatch = brandCompositionMap[key];
        bestLength = key.length;
      }
    }
  }

  if (bestMatch) {
    return bestMatch;
  }

  // Check aliases across all entries
  for (var j = 0; j < keys.length; j++) {
    var entry = brandCompositionMap[keys[j]];
    if (entry.aliases && Array.isArray(entry.aliases)) {
      for (var k = 0; k < entry.aliases.length; k++) {
        if (entry.aliases[k].toLowerCase() === searchTerm) {
          return entry;
        }
      }
    }
  }

  // Fallback: search in name field
  for (var m = 0; m < keys.length; m++) {
    var e = brandCompositionMap[keys[m]];
    if (e.name && e.name.toLowerCase().indexOf(searchTerm) !== -1) {
      return e;
    }
  }

  // Fallback: search in composition field
  for (var n = 0; n < keys.length; n++) {
    var ent = brandCompositionMap[keys[n]];
    if (ent.composition && ent.composition.toLowerCase().indexOf(searchTerm) !== -1) {
      return ent;
    }
  }

  return null;
}

module.exports = { brandCompositionMap, lookupBrand };
